context_info = ()
for d in context:
    r = llm_query("Here is a document:\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT\nExtract any details relevant to identifying a TV show (series/miniseries) that matches ALL of these constraints, and provide evidence from the document if present:\n- The show is based on a famous novel.\n- Somewhere between 5 to 20 years passed from when the author started writing the novel to when it was published.\n- One of the lead actors in the show was born in a year when U.S. GDP per capita was roughly $3,000 (historically about 1960).\n- The actors who portrayed the leading pair in the show did not work together again for more than a decade after the show.\nFor any matching show mentioned in the document, list:\n- Show title and year\n- Novel and author; approximate start-writing year and publication year; the gap (years)\n- Names and birth years of the two lead actors, and which one was born in ~1960\n- The protagonist character name and the actor who plays the protagonist's father in the show\n- Supporting quotes from the document\nIf the document does not contain relevant info, answer: No relevant info.")
    context_info = context_info + (r,)

general = llm_query("Solve this riddle using general knowledge (not limited to any single document):\nGoal: As of 2023, find the name of the actor who plays the father of the protagonist of a TV show (series/miniseries, not a film) based on a famous novel, given these constraints:\n- 5 to 20 years passed from when the author started writing the novel to its publication.\n- The year in which one of the lead actors in the show was born, the U.S. GDP per capita was about $3,000 (historically around 1960).\n- The actors who portrayed the leading pair did not work together again for more than a decade.\nThink step by step: propose the likeliest show, the novel and author, estimate the writing start and publication years and the gap; identify the leading pair and which one was born in ~1960; then name the protagonist’s father character and the actor who plays him in the show. End with: Answer: <actor name only>.")

final_prompt = "Here are document-based extractions:\n" + "\n\n".join(context_info) + "\n\nHere is a general-knowledge reasoning attempt:\n" + general + "\n\nBased on everything above, answer the user’s question:\nAs of 2023, can you find out the name of the actor who plays the father of the protagonist of a TV show based on a famous novel? The constraints are:\n- 5 to 20 years passed from when the author started writing the novel to when it was published.\n- The year in which one of the lead actors in the show was born, the U.S. GDP Per Capita was about $3,000 (historically ~1960).\n- The actors who portrayed the leading pair in the show did not work together again for more than a decade.\nOutput ONLY the actor’s full name who plays the protagonist’s father in that TV show (series/miniseries). No explanations, no extra words, no punctuation."

answer = llm_query(final_prompt)
return_result(answer.strip())